import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Detect input type: adjacency matrix if square and binary entries
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for i in range(n):
            if len(adj[i]) != n:
                all_binary = False
                break
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets for efficient access
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n and j != i:
                    neighbors[i].add(j)

    # Ensure undirected graph
    for i in range(n):
        for j in list(neighbors[i]):
            if i not in neighbors[j]:
                neighbors[j].add(i)

    # Trivial cases
    if n == 1:
        return [0]
    if not any(neighbors[i] for i in range(n)):
        return [0] * n

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR with optimized saturation update and tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        if n == 0:
            return color
        # Start with vertex of maximum degree
        v = max(range(n), key=lambda x: len(neighbors[x]))
        color[v] = 0
        uncolored.remove(v)
        for u in neighbors[v]:
            if u in uncolored:
                sat[u] = 1

        while uncolored:
            max_sat = -1
            candidates = []
            # Recompute degree in uncolored subgraph for tie-breaking
            deg_uncolored = [0] * n
            for v in uncolored:
                cnt = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        cnt += 1
                deg_uncolored[v] = cnt
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if max_sat == -1:  # all saturation zero, pick max degree in uncolored
                v = max(uncolored, key=lambda x: deg_uncolored[x])
            else:
                # Tie-break: max degree in uncolored subgraph
                v = max(candidates, key=lambda x: deg_uncolored[x])
            # Assign smallest available color
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored and color[u] == -1:
                    # Check if color c is new for u's saturation
                    found = False
                    for w in neighbors[u]:
                        if color[w] == c:
                            found = True
                            break
                    if not found:
                        sat[u] += 1
        return color

    # Helper: RLF (Recursive Largest First) with optimized set operations
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = []
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([u for u in neighbors[x] if u in uncolored]))
            S.append(v)
            # Partition: U (eligible), W (ineligible)
            U = uncolored - {v}
            W = set(u for u in neighbors[v] if u in uncolored)
            # While there are eligible vertices
            while U:
                # Select u in U with max neighbors in W
                best_u = -1
                max_neighbors_in_W = -1
                for u in U:
                    count = sum(1 for w in neighbors[u] if w in W)
                    if count > max_neighbors_in_W:
                        max_neighbors_in_W = count
                        best_u = u
                    elif count == max_neighbors_in_W:
                        # Tie-break: min degree in G[U]
                        deg_u = sum(1 for w in neighbors[u] if w in U)
                        deg_best = sum(1 for w in neighbors[best_u] if w in U) if best_u != -1 else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                if best_u == -1:
                    break  # should not happen if U non-empty
                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in neighbors[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= set(S)
            c += 1
        return color

    # Helper: smallest-last ordering
    def smallest_last():
        if n == 0:
            return []
        deg = [len(neighbors[i]) for i in range(n)]
        adj_set = [set(neighbors[i]) for i in range(n)]
        remaining = set(range(n))
        order = []
        for _ in range(n):
            v = min(remaining, key=lambda x: deg[x])
            order.append(v)
            remaining.remove(v)
            for u in adj_set[v]:
                if u in remaining:
                    deg[u] -= 1
        return order[::-1]

    # Helper: Kempe chain reduction for color class elimination (optimized)
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        max_color = max(coloring)
        if max_color <= 0:
            return coloring
        # Try to eliminate color classes from highest down
        for target_color in range(max_color, 0, -1):
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue
            changed = True
            while changed and verts:
                changed = False
                v = verts.pop()
                # Try direct move to lower color
                neighbor_colors = {coloring[u] for u in neighbors[v] if coloring[u] != -1}
                for c in range(target_color):
                    if c not in neighbor_colors:
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    continue
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue
                    # Build (target_color, c)-Kempe chain containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            for u in neighbors[node]:
                                if coloring[u] == target_color or coloring[u] == c:
                                    if u not in visited:
                                        stack.append(u)
                    # Check if any neighbor of v with color c is in this component
                    has_c_neighbor_in_comp = any(coloring[u] == c and u in component for u in neighbors[v])
                    if not has_c_neighbor_in_comp:
                        # Swap colors in component
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            elif coloring[node] == c:
                                coloring[node] = target_color
                        changed = True
                        break
                if changed:
                    # Restart checking this color class as it may have changed
                    verts = [v for v in range(n) if coloring[v] == target_color]
                    break
            if not any(coloring[v] == target_color for v in range(n)):
                # Successfully eliminated target_color, shift higher colors down
                for v in range(n):
                    if coloring[v] > target_color:
                        coloring[v] -= 1
                break  # restart reduction from new max color
        return coloring

    # Helper: Bitmask-based exact coloring for small subgraphs (n <= 20)
    def exact_color_bitmask():
        nonlocal n
        if n > 20:
            return None
        # Precompute neighbor masks
        neighbor_mask = [0] * n
        for i in range(n):
            mask = 0
            for j in neighbors[i]:
                mask |= (1 << j)
            neighbor_mask[i] = mask

        # Try k from lower bound to n
        lb = max(1, max(len(neighbors[i]) for i in range(n))) if n > 0 else 0
        lb = max(lb, 1)  # at least 1 if any edge
        # Clique lower bound via greedy
        tmp = [-1] * n
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        for v in order:
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if tmp[u] != -1:
                    used[tmp[u]] = True
            c = 0
            while used[c]:
                c += 1
            tmp[v] = c
        lb = max(lb, max(tmp) + 1 if n > 0 else 0)

        for k in range(lb, n + 1):
            colors = [-1] * n
            # Use recursion with ordering by degree
            order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)

            def backtrack(idx):
                if idx == n:
                    return True
                v = order[idx]
                # Try each color
                for c in range(k):
                    # Check if color c is allowed
                    mask = 0
                    for u in neighbors[v]:
                        if colors[u] == c:
                            mask = 1
                            break
                    if mask == 0:
                        colors[v] = c
                        if backtrack(idx + 1):
                            return True
                        colors[v] = -1
                return False

            if backtrack(0):
                return colors[:]
        return None  # should not happen

    # Main: try multiple heuristics and keep best
    best_coloring = None
    best_num_colors = float('inf')

    # Try exact for small graphs
    if n <= 20:
        col_exact = exact_color_bitmask()
        if col_exact is not None:
            num_colors = max(col_exact) + 1 if n > 0 else 0
            if num_colors < best_num_colors:
                best_num_colors = num_colors
                best_coloring = col_exact[:]

    # Run DSATUR
    col_dsatur = dsatur()
    num_colors = max(col_dsatur) + 1 if n > 0 else 0
    if num_colors < best_num_colors:
        best_num_colors = num_colors
        best_coloring = col_dsatur[:]

    # Run RLF
    col_rlf = rlf()
    num_colors = max(col_rlf) + 1 if n > 0 else 0
    if num_colors < best_num_colors:
        best_num_colors = num_colors
        best_coloring = col_rlf[:]

    # Run smallest-last greedy
    order_sl = smallest_last()
    col_sl = greedy_color(order_sl)
    num_colors = max(col_sl) + 1 if n > 0 else 0
    if num_colors < best_num_colors:
        best_num_colors = num_colors
        best_coloring = col_sl[:]

    # Run Welsh-Powell (degree descending)
    order_wp = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    col_wp = greedy_color(order_wp)
    num_colors = max(col_wp) + 1 if n > 0 else 0
    if num_colors < best_num_colors:
        best_num_colors = num_colors
        best_coloring = col_wp[:]

    # Run a few random orders with greedy
    for _ in range(15):  # slightly increased for better chance
        order_rand = list(range(n))
        random.shuffle(order_rand)
        col_rand = greedy_color(order_rand)
        num_colors = max(col_rand) + 1 if n > 0 else 0
        if num_colors < best_num_colors:
            best_num_colors = num_colors
            best_coloring = col_rand[:]

    # Apply Kempe chain reduction to the best found
    if best_coloring is not None and n > 0:
        reduced = kempe_reduce(best_coloring[:])
        num_colors_reduced = max(reduced) + 1
        if num_colors_reduced < best_num_colors:
            best_num_colors = num_colors_reduced
            best_coloring = reduced

    return best_coloring
